QByteArray fingerprint(QETProject &project){QStringList parts;for(auto *folio:project.diagrams()){for(auto *element:folio->elements())parts<<element->uuid().toString()+QString::number(element->pos().x())+":"+QString::number(element->pos().y())+":"+QString::number(element->rotation());for(auto *wire:folio->conductors()){QString path;for(int i=0;i<wire->path().elementCount();++i){auto e=wire->path().elementAt(i);path+=QString::number(e.x)+":"+QString::number(e.y)+";";}parts<<path;}}parts.sort();return parts.join('|').toUtf8();}
